BEGIN;

DO $$BEGIN IF pg_catalog.to_regprocedure('extensions.digest(bytea,text)') IS NULL THEN RAISE EXCEPTION 'sales_collective_requires_extensions_digest_sha256';END IF;END;$$;

CREATE OR REPLACE FUNCTION public.sales_collective_period_key_v1(p_tenant_id uuid,p_period_id uuid)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,public,extensions AS $$
 SELECT encode(extensions.digest(convert_to(p_tenant_id::text||':'||p_period_id::text,'UTF8'),'sha256'),'hex');
$$;
REVOKE ALL ON FUNCTION public.sales_collective_period_key_v1(uuid,uuid) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.sales_collective_summary_v2(p_period_key text DEFAULT NULL,p_month integer DEFAULT NULL,p_year integer DEFAULT NULL,p_page integer DEFAULT 1,p_page_size integer DEFAULT 25)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,extensions AS $$
DECLARE
 v_tenant uuid:=public.auth_tenant_id();v_actor uuid:=auth.uid();v_role public."SalesMemberRole":=public.sales_membership_role();
 v_allowed boolean:=false;v_period uuid;v_start date;v_end date;v_status public."SalesPeriodStatus";v_timezone text;v_as_of date;v_filter_start date;v_filter_end date;
 v_metrics jsonb;v_realized numeric:=0;v_ideal numeric:=0;v_remaining integer:=0;v_required_percent numeric:=0;
 v_member_count integer:=0;v_rank_total integer:=0;v_sales_count bigint:=0;v_pieces_total bigint:=0;v_freight numeric:=0;v_gross numeric:=0;v_freight_percent numeric:=0;
 v_available_periods jsonb:='[]'::jsonb;v_goals jsonb:='[]'::jsonb;
 v_installments jsonb:='[]'::jsonb;v_payment_methods jsonb:='[]'::jsonb;v_sellers jsonb:='[]'::jsonb;
BEGIN
 IF v_tenant IS NULL OR v_actor IS NULL OR v_role IS NULL OR v_role NOT IN('ADMIN','CONSULTANT') THEN RAISE EXCEPTION 'sales_collective_access_denied' USING ERRCODE='42501';END IF;
 IF(p_period_key IS NOT NULL AND p_period_key!~'^[0-9a-f]{64}$')OR(p_month IS NOT NULL AND p_month NOT BETWEEN 1 AND 12)OR(p_year IS NOT NULL AND p_year NOT BETWEEN 2000 AND 2200)OR(p_month IS NOT NULL AND p_year IS NULL)OR p_page IS NULL OR p_page<1 OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'sales_collective_filter_validation' USING ERRCODE='22023';END IF;
 SELECT COALESCE(sc.timezone,'America/Sao_Paulo'),COALESCE(sc.allow_team_aggregates,false)INTO v_timezone,v_allowed FROM(SELECT 1)q LEFT JOIN public.sales_config sc ON sc.tenant_id=v_tenant;
 v_as_of:=(now()AT TIME ZONE v_timezone)::date;
 IF p_year IS NOT NULL THEN v_filter_start:=CASE WHEN p_month IS NULL THEN make_date(p_year,1,1)ELSE make_date(p_year,p_month,1)END;v_filter_end:=(v_filter_start+(CASE WHEN p_month IS NULL THEN interval '1 year' ELSE interval '1 month' END)-interval '1 day')::date;END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('key',public.sales_collective_period_key_v1(v_tenant,sp.id),'starts_on',sp.starts_on,'ends_on',sp.ends_on,'status',sp.status)ORDER BY sp.starts_on DESC,sp.ends_on DESC),'[]'::jsonb)INTO v_available_periods FROM public.sales_periods sp WHERE sp.tenant_id=v_tenant;
 IF NOT v_allowed THEN RETURN jsonb_build_object('allowed',false,'role',v_role,'available_periods',v_available_periods,'filters',jsonb_build_object('period_key',p_period_key,'month',p_month,'year',p_year),'seller_ranking',jsonb_build_object('page',p_page,'page_size',p_page_size,'total',0,'items','[]'::jsonb));END IF;
 SELECT sp.id,sp.starts_on,sp.ends_on,sp.status INTO v_period,v_start,v_end,v_status FROM public.sales_periods sp WHERE sp.tenant_id=v_tenant AND(p_period_key IS NULL OR public.sales_collective_period_key_v1(v_tenant,sp.id)=p_period_key)AND(v_filter_start IS NULL OR(sp.starts_on<=v_filter_end AND sp.ends_on>=v_filter_start))ORDER BY(sp.status='OPEN')DESC,sp.starts_on DESC LIMIT 1;
 IF v_period IS NULL THEN RAISE EXCEPTION 'sales_not_found_or_out_of_scope' USING ERRCODE='P0002';END IF;
 v_metrics:=public.sales_metrics_internal_v1(v_tenant,v_period,NULL,v_as_of);v_realized:=COALESCE((v_metrics->>'realized_value')::numeric,0);v_ideal:=COALESCE((v_metrics->>'ideal_pace_percent')::numeric,0);v_remaining:=COALESCE((v_metrics->>'business_days_remaining')::integer,0);
 SELECT count(*)::integer INTO v_member_count FROM public.sales_memberships sm WHERE sm.tenant_id=v_tenant AND sm.role='CONSULTANT' AND sm.is_active;
 SELECT count(*),COALESCE(sum(s.pieces_total),0),COALESCE(sum(s.freight_value),0),COALESCE(sum(s.sale_value),0)INTO v_sales_count,v_pieces_total,v_freight,v_gross FROM public.sales s WHERE s.tenant_id=v_tenant AND s.period_id=v_period AND s.status='CLOSED';
 v_freight_percent:=CASE WHEN v_gross=0 THEN 0 ELSE round(v_freight/v_gross*100,2)END;
 WITH identities(key,label,ordinal)AS(VALUES('META_1','Meta 1',1),('META_2','Meta 2',2),('META_3','Meta 3',3),('CHALLENGE','Desafio',4),('QUARTERLY','Trimestral',5)),individual_progress AS(SELECT sg.provisioning_key key,sga.profile_id,CASE WHEN sga.target_value_snapshot=0 THEN 0 ELSE COALESCE(sum(s.sale_value-s.discount_value),0)/sga.target_value_snapshot*100 END progress_percent FROM public.sales_goal_assignments sga JOIN public.sales_goals sg ON sg.tenant_id=sga.tenant_id AND sg.id=sga.goal_id LEFT JOIN public.sales s ON s.tenant_id=sga.tenant_id AND s.period_id=sga.period_id AND s.consultant_profile_id=sga.profile_id AND s.status='CLOSED' WHERE sga.tenant_id=v_tenant AND sga.period_id=v_period AND sga.profile_id IS NOT NULL AND sga.is_active AND((sg.provisioning_key IN('META_1','META_2','META_3','CHALLENGE')AND sga.goal_scope_snapshot='INDIVIDUAL')OR(sg.provisioning_key='QUARTERLY' AND sga.goal_scope_snapshot='QUARTERLY'))AND(sga.valid_from_snapshot IS NULL OR sga.valid_from_snapshot<=v_end)AND(sga.valid_until_snapshot IS NULL OR sga.valid_until_snapshot>=v_start)GROUP BY sg.provisioning_key,sga.profile_id,sga.target_value_snapshot),individual_stats AS(SELECT key,count(*)participant_count,round(avg(progress_percent),2)progress_percent FROM individual_progress GROUP BY key),collective_stats AS(SELECT count(*)assignment_count,CASE WHEN max(sga.target_value_snapshot)=0 THEN 0 ELSE round(v_realized/max(sga.target_value_snapshot)*100,2)END progress_percent FROM public.sales_goal_assignments sga JOIN public.sales_goals sg ON sg.tenant_id=sga.tenant_id AND sg.id=sga.goal_id WHERE sga.tenant_id=v_tenant AND sga.period_id=v_period AND sga.profile_id IS NULL AND sga.is_active AND sga.goal_scope_snapshot='COLLECTIVE' AND sg.provisioning_key='COLLECTIVE' AND(sga.valid_from_snapshot IS NULL OR sga.valid_from_snapshot<=v_end)AND(sga.valid_until_snapshot IS NULL OR sga.valid_until_snapshot>=v_start)),goal_rows AS(SELECT i.ordinal,jsonb_build_object('key',i.key,'label',i.label,'available',COALESCE(st.participant_count,0)>=3,'suppressed',COALESCE(st.participant_count,0)<3,'minimum_participants',3,'progress_percent',CASE WHEN COALESCE(st.participant_count,0)>=3 THEN st.progress_percent END,'ideal_pace_percent',CASE WHEN COALESCE(st.participant_count,0)>=3 THEN v_ideal END,'necessary_per_business_day_percent',CASE WHEN COALESCE(st.participant_count,0)<3 THEN NULL WHEN v_remaining=0 THEN 0 ELSE round(GREATEST(100-st.progress_percent,0)/v_remaining,2)END)payload FROM identities i LEFT JOIN individual_stats st ON st.key=i.key UNION ALL SELECT 6,jsonb_build_object('key','COLLECTIVE','label','Meta coletiva','available',cs.assignment_count>0,'suppressed',false,'progress_percent',CASE WHEN cs.assignment_count>0 THEN cs.progress_percent END,'ideal_pace_percent',CASE WHEN cs.assignment_count>0 THEN v_ideal END,'necessary_per_business_day_percent',CASE WHEN cs.assignment_count=0 THEN NULL WHEN v_remaining=0 THEN 0 ELSE round(GREATEST(100-cs.progress_percent,0)/v_remaining,2)END)FROM collective_stats cs)SELECT COALESCE(jsonb_agg(payload ORDER BY ordinal),'[]'::jsonb)INTO v_goals FROM goal_rows;
 WITH bucket_counts AS(SELECT s.installments bucket,count(*)sales_count FROM public.sales s WHERE s.tenant_id=v_tenant AND s.period_id=v_period AND s.status='CLOSED' GROUP BY s.installments),stats AS(SELECT COALESCE(sum(sales_count)FILTER(WHERE sales_count<3),0)hidden_count FROM bucket_counts),ranked AS(SELECT b.*,row_number()OVER(ORDER BY b.sales_count,b.bucket)complement_order FROM bucket_counts b WHERE b.sales_count>=3),visible AS(SELECT r.* FROM ranked r CROSS JOIN stats st WHERE NOT(st.hidden_count IN(1,2)AND r.complement_order=1))SELECT COALESCE(jsonb_agg(jsonb_build_object('position',x.position,'label',x.bucket::text||'x','sales_percent',x.sales_percent,'suppressed',false)ORDER BY x.position,x.bucket),'[]'::jsonb)INTO v_installments FROM(SELECT dense_rank()OVER(ORDER BY v.sales_count DESC)position,v.bucket,round(v.sales_count::numeric/NULLIF(v_sales_count,0)*100,2)sales_percent FROM visible v)x;
 WITH bucket_counts AS(SELECT s.payment_method_id,pm.name method_name,count(*)sales_count FROM public.sales s JOIN public.sales_payment_methods pm ON pm.tenant_id=s.tenant_id AND pm.id=s.payment_method_id WHERE s.tenant_id=v_tenant AND s.period_id=v_period AND s.status='CLOSED' GROUP BY s.payment_method_id,pm.name),stats AS(SELECT COALESCE(sum(sales_count)FILTER(WHERE sales_count<3),0)hidden_count FROM bucket_counts),ranked AS(SELECT b.*,row_number()OVER(ORDER BY b.sales_count,public.sales_collective_period_key_v1(v_tenant,b.payment_method_id))complement_order FROM bucket_counts b WHERE b.sales_count>=3),visible AS(SELECT r.* FROM ranked r CROSS JOIN stats st WHERE NOT(st.hidden_count IN(1,2)AND r.complement_order=1))SELECT COALESCE(jsonb_agg(jsonb_build_object('position',x.position,'label',x.method_name,'sales_percent',x.sales_percent,'suppressed',false,'tied',x.tie_count>1)ORDER BY x.position,x.stable_order),'[]'::jsonb)INTO v_payment_methods FROM(SELECT dense_rank()OVER(ORDER BY v.sales_count DESC)position,v.method_name,round(v.sales_count::numeric/NULLIF(v_sales_count,0)*100,2)sales_percent,count(*)OVER(PARTITION BY v.sales_count)tie_count,public.sales_collective_period_key_v1(v_tenant,v.payment_method_id)stable_order FROM visible v)x;
 IF v_member_count>=3 THEN SELECT count(*)INTO v_rank_total FROM public.sales_memberships sm WHERE sm.tenant_id=v_tenant AND sm.role='CONSULTANT' AND sm.is_active;SELECT COALESCE(jsonb_agg(jsonb_build_object('position',x.position,'label','Posição '||x.position,'contribution_percent',x.contribution_percent,'tied',x.tie_count>1)ORDER BY x.position,x.stable_order),'[]'::jsonb)INTO v_sellers FROM(SELECT ranked.* FROM(SELECT dense_rank()OVER(ORDER BY q.realized DESC)position,CASE WHEN v_realized=0 THEN 0 ELSE round(q.realized/v_realized*100,2)END contribution_percent,count(*)OVER(PARTITION BY q.realized)tie_count,public.sales_collective_period_key_v1(v_tenant,q.profile_id)stable_order FROM(SELECT sm.profile_id,COALESCE(sum(s.sale_value-s.discount_value),0)realized FROM public.sales_memberships sm LEFT JOIN public.sales s ON s.tenant_id=sm.tenant_id AND s.consultant_profile_id=sm.profile_id AND s.period_id=v_period AND s.status='CLOSED' WHERE sm.tenant_id=v_tenant AND sm.role='CONSULTANT' AND sm.is_active GROUP BY sm.profile_id)q)ranked ORDER BY ranked.position,ranked.stable_order LIMIT p_page_size OFFSET(p_page-1)*p_page_size)x;END IF;
 RETURN jsonb_build_object('allowed',true,'role',v_role,'period',jsonb_build_object('key',public.sales_collective_period_key_v1(v_tenant,v_period),'starts_on',v_start,'ends_on',v_end,'status',v_status),'available_periods',v_available_periods,'filters',jsonb_build_object('period_key',p_period_key,'month',p_month,'year',p_year),'pace',jsonb_build_object('achieved_percent',COALESCE((v_metrics->>'collective_percent')::numeric,0),'ideal_pace_percent',v_ideal,'necessary_per_business_day_percent',CASE WHEN v_remaining=0 THEN 0 ELSE round(GREATEST(100-COALESCE((v_metrics->>'collective_percent')::numeric,0),0)/v_remaining,2)END,'business_days_remaining',v_remaining),'goals',v_goals,'aggregates',jsonb_build_object('sales_count',v_sales_count,'pieces_total',v_pieces_total,'freight_share_percent',v_freight_percent),'installments',jsonb_build_object('minimum_bucket_size',3,'has_suppressed_buckets',v_installments='[]'::jsonb OR jsonb_array_length(v_installments)<(SELECT count(*)FROM(SELECT s.installments FROM public.sales s WHERE s.tenant_id=v_tenant AND s.period_id=v_period AND s.status='CLOSED' GROUP BY s.installments)q),'items',v_installments),'payment_methods',jsonb_build_object('minimum_bucket_size',3,'has_suppressed_buckets',v_payment_methods='[]'::jsonb OR jsonb_array_length(v_payment_methods)<(SELECT count(*)FROM(SELECT s.payment_method_id FROM public.sales s WHERE s.tenant_id=v_tenant AND s.period_id=v_period AND s.status='CLOSED' GROUP BY s.payment_method_id)q),'items',v_payment_methods),'seller_ranking',jsonb_build_object('minimum_team_size',3,'suppressed',v_member_count<3,'page',p_page,'page_size',p_page_size,'total',v_rank_total,'items',v_sellers));
END;$$;

REVOKE EXECUTE ON FUNCTION public.sales_collective_summary_v1(uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.sales_collective_summary_v2(text,integer,integer,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_collective_summary_v2(text,integer,integer,integer,integer) TO authenticated;

COMMIT;
